-- composition of rule kernels distinct_aggregate_rewrite x filter_pushdown (duckdb), template cte_twice
WITH ka AS (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT []::text[] AS c0, 10.0::float8 AS c1, a1.c3 AS c2 FROM t3 AS a1 WHERE a1.c1 UNION ALL SELECT ARRAY['1'::text] AS c0, 100.0::float8 AS c1, '00:00:00.000001'::interval AS c2), kb AS (SELECT ((COUNT (DISTINCT a1.c5) % 1000)::int - 1) AS c0, a1.c5 AS c1, 'A'::text AS c2, 0::bigint AS c3 FROM t3 AS a1 GROUP BY a1.c2, a1.c5) SELECT (SELECT count(*) FROM ka) + (SELECT count(*) FROM kb) + (SELECT count(*) FROM ka);
-- pgfuzz:check kernel:cte_twice SELECT 2 * (SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT []::text[] AS c0, 10.0::float8 AS c1, a1.c3 AS c2 FROM t3 AS a1 WHERE a1.c1 UNION ALL SELECT ARRAY['1'::text] AS c0, 100.0::float8 AS c1, '00:00:00.000001'::interval AS c2) AS ka) + (SELECT count(*) FROM (SELECT ((COUNT (DISTINCT a1.c5) % 1000)::int - 1) AS c0, a1.c5 AS c1, 'A'::text AS c2, 0::bigint AS c3 FROM t3 AS a1 GROUP BY a1.c2, a1.c5) AS kb)
